targets.example:
// client
for (const target of kcds.characters.Follow.targets()) {
  console.log(`${target.kind} ${target.name}`);
}

targets.exampleCs:
// client
foreach (var target in Follow.Targets())
{
    Log.Info($"{target["kind"]} {target["name"]}");
}

canStart.example:
// client
const { Follow } = kcds.characters;

const nearest = Follow.targets()[0];
if (nearest && Follow.canStart(nearest)) {
  Follow.start(nearest);
}

canStart.exampleCs:
// client

var nearest = Follow.Targets()[0];
if (nearest && Follow.CanStart(nearest))
{
    Follow.Start(nearest);
}

start.example:
// client: a prisoner led by a running guard
kcds.core.Events.on('jail:lead', (data) => {
  kcds.characters.Follow.start(data.guardId, { hint: false, playerCanStop: false, distance: 1.5, pace: 'run' });
});

start.exampleCs:
// client: a prisoner led by a running guard
Events.On("jail:lead", (JsValue data) =>
{
    Follow.Start(data["guardId"], new { hint = false, playerCanStop = false, distance = 1.5, pace = "run" });
});

getTarget.example:
// client
const target = kcds.characters.Follow.getTarget();
if (target) {
  console.log(`following ${target.name}`);
}

getTarget.exampleCs:
// client
var target = Follow.GetTarget();
if (target)
{
    Log.Info($"following {target["name"]}");
}

isPending.example:
// client
if (kcds.characters.Follow.isPending()) {
  console.log('the follow starts in a moment');
}

isPending.exampleCs:
// client
if (Follow.IsPending())
{
    Log.Info("the follow starts in a moment");
}

stop.example:
// client
const { Follow } = kcds.characters;

kcds.ui.Key.bind('escape', () => {
  if (Follow.getTarget()) {
    Follow.stop();
  }
});

stop.exampleCs:
// client

Key.Bind("escape", new Action(() =>
{
    if (Follow.GetTarget())
    {
        Follow.Stop();
    }
}));
